  [/^(.+?)s? kalender hentes automatisk hver nat\.$/, m => `The calendar of ${m[1]} is fetched automatically every night.`],
  [/^(.+?) Se kommende arrangementer og faste tilbud hos .*$|^(.+?) Se kommende…$/, m => { const en = translateText(m[1] ?? m[2]!); return en === null ? null : `${en} See upcoming events…`; }],
  [/^Læs hele beskrivelsen hos (.+) →$/, m => `Read the full description at ${m[1]} →`],
  [/^Kort over (.+)$/, m => `Map of ${m[1]}`],
  // Counts.
  [/^(\d+) arrangement(?:er)?$/, m => n(m[1]!, "event", "events")],
  [/^(\d+) arrangement(?:er)? – dag for dag$/, m => `${n(m[1]!, "event", "events")} – day by day`],
  [/^(.+) – (\d+) arrangement(?:er)? den næste måned$/, m => `${t(m[1]!)} – ${n(m[2]!, "event", "events")} in the next month`],
  [/^\+ (\d+) mere fra (.+)$/, m => `+ ${m[1]} more from ${m[2]}`],
  [/^Også (.+)$/, m => hasDate(m[1]!) ? `Also ${englishDates(m[1]!)}` : null],
  [/^Alle (\d+) →$/, m => `All ${m[1]} →`],
  [/^Se hele kalenderen – (\d+) arrangement(?:er)?$/, m => `See the whole calendar – ${n(m[1]!, "event", "events")}`],
  [/^Vi vil have flere ud at opleve byen sammen\. Find noget blandt (\d+) arrangementer i Aarhus – fra de store scener til de små spillesteder og foreninger, som fortjener at blive opdaget – og tryk "Jeg vil gerne med!" Så samler vi en lille flok, du kan følges med\.$/,
    m => `We want more people out experiencing the city together. Find something among ${m[1]} events in Aarhus – from the big stages to the small music venues and associations that deserve to be discovered – and tap "I'd like to come along!" Then we'll gather a small group for you to go with.`],
  [/^(\d+) af (\d+) · plads til (\d+) mere$/, m => `${m[1]} of ${m[2]} · room for ${m[3]} more`],
  [/^(\d+) af (\d+) pladser taget$/, m => `${m[1]} of ${m[2]} places taken`],
  [/^(\d+) interesserede?$/, m => `${m[1]} interested`],
  [/^Velkommen, (.+)!$/, m => `Welcome, ${m[1]}!`],
  [/^Hej (\S+)$/, m => `Hi ${m[1]}`],
  [/^· (.+)$/, m => { const en = translateText(m[1]!); return en === null ? null : `· ${en}`; }],
  [/^Du har været med en flok (\d+) gange?\.$/, m => `You've been with a group ${m[1]} ${m[1] === "1" ? "time" : "times"}.`],
  [/^(\d+) (?:anden|andre) er interesseret\.$/, m => `${m[1]} ${m[1] === "1" ? "other person is" : "others are"} interested.`],
  [/^Vi samler en flok, når I er (\d+), og giver dig besked\.$/, m => `We'll gather a group when there are ${m[1]} of you, and let you know.`],
  [/^Beskeden er for lang\. Højst (\d+) tegn\.$/, m => `The message is too long. At most ${m[1]} characters.`],
  [/^Fordi du kan lide (.+)$/, m => `Because you like ${m[1]!.split(/ og |, /).map(x => t(x)).join(" and ")}`],
  [/^(\d+)–(\d+) år$/, m => `${m[1]}–${m[2]}`],
  // Descriptions with a number.
  [/^Ting at lave i Aarhus: koncerter, teater, foredrag og meget mere – (\d+) kommende arrangementer\. Mød nye mennesker: vis interesse, så samler vi en lille flok, du kan følges med\.$/,
    m => `Things to do in Aarhus: concerts, theatre, talks and much more – ${m[1]} upcoming events. Meet new people: show interest, and we'll gather a small group for you to go with.`],
  [/^Kalender for Aarhus: (\d+) kommende arrangementer fra lokale arrangører – dag for dag\. Find en flok at følges med\.$/,
    m => `Events calendar for Aarhus: ${m[1]} upcoming events from local organisers – day by day. Find a group to go with.`],
  [/^Det sker i dag i Aarhus: (\d+) arrangement(?:er)?\. Find en flok at følges med\.$/, m => `What's on in Aarhus today: ${n(m[1]!, "event", "events")}. Find a group to go with.`],
  [/^Det sker i weekenden i Aarhus: (\d+) arrangement(?:er)?\. Find en flok at følges med\.$/, m => `What's on in Aarhus this weekend: ${n(m[1]!, "event", "events")}. Find a group to go with.`],
  [/^Det sker i Aarhus: (\d+) kommende arrangement(?:er)? fra lokale arrangører\. Find en flok at følges med\.$/, m => `What's on in Aarhus: ${m[1]} upcoming events from local organisers. Find a group to go with.`],
  [new RegExp(`^(${DATE}(?: kl\\. [\\d.]+)?) i (.+)$`), m => `${englishDates(m[1]!)} at ${m[2]!.replace(/ · Gratis\b/, " · Free")}`],
  // Event facts.
  [/^Tid: (.+)$/, m => `Time: ${englishDates(m[1]!)}`],
  [/^Billede: (.+)$/, m => `Image: ${m[1]}`],
  [/^Underviser: (.+)$/, m => `Teacher: ${m[1]}`],
  [/^Ifølge beskrivelsen: (.+)$/, m => `According to the description: ${m[1]}`],
  [/^Sidst kontrolleret (.+)\. Ret eller aflys altid hos arrangøren\.$/, m => `Last checked ${englishDates(m[1]!)}. Changes and cancellations are always made with the organiser.`],
  [/^Fjern filter: (.+)$/, m => `Remove filter: ${t(m[1]!)}`],
  [/^Op til (\d+) kr\.$/, m => `Up to ${m[1]} kr.`],
  // A line of parts ("Lysets Hus, Aarhus C · Gratis · til 18.30", "Meditation · Aarhus").
  [/ · /, m => { const s = m.input; const en = s.split(" · ").map(part).join(" · "); return en === s ? null : en; }],
  // A date or a time on its own ("Søndag 11. oktober", "kl. 15.30–18.00").
  [/./, m => onlyDate(m.input) ? englishDates(m.input) : null]
